import type { DocumentFormat } from '../types/document'

/**
 * SYNTHETIC SAMPLE PACK for demo batch CP-LDH-2026-001.
 * The files in /public/samples were generated by scripts/sample-pack and carry a
 * visible "synthetic sample" banner. All parties and figures are fictional.
 */
export interface SamplePackFile {
  key: string
  fileName: string
  format: DocumentFormat
  mimeType: string
  title: string
  description: string
}

