/** Evidence deliberately left out of the pack, so the demo shows a real gap. */
export const SAMPLE_PACK_OMISSION =
  'Job-worker furnace energy records are intentionally not included, matching the open issue on the dashboard.'

export function samplePackUrl(file: SamplePackFile): string {
  return `${import.meta.env.BASE_URL}samples/${encodeURIComponent(file.fileName)}`
}

export function findSampleFile(key: string | undefined): SamplePackFile | undefined {
  return key ? SAMPLE_PACK_FILES.find((file) => file.key === key) : undefined
}
